paragraph.math:
$$\begin{array}{l}
  {\left. F(x) + C \right|_{a}^{b}{= \left\lbrack {F(b) + C} \right\rbrack - \left\lbrack {F(a) + C} \right\rbrack}} \\
  {\phantom{\left. F(x) + C \right|_{a}^{b}}{= F(b) + C - F(a) - C}} \\
  {\phantom{\left. F(x) + C \right|_{a}^{b}}{= F(b) - F(a)}}
  \end{array}$$

$$\begin{array}{l}
  {\int_{0}^{2}\left( x + e^{x} \right)dx = \left. \frac{1}{2}x^{2} + e^{x} \right|_{0}^{2}} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = \left\lbrack \frac{1}{2}(2)^{2} + e^{2} \right\rbrack - \left\lbrack \frac{1}{2}(0) + e^{0} \right\rbrack} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = 2 + e^{2} - 1} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = e^{2} + 1}
  \end{array}$$
